import math
import operator
from functools import lru_cache

import numpy as np
from scipy.optimize import minimize
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit.transpiler import CouplingMap
from qiskit_aer import AerSimulator


def _integer_argument(name, value, minimum):
    try:
        value = operator.index(value)
    except TypeError as exc:
        raise ValueError(f"{name} must be an integer.") from exc
    if value < minimum:
        raise ValueError(f"{name} must be at least {minimum}.")
    return int(value)


def _normalize_graph(graph_vertices, graph_edges):
    vertices = list(graph_vertices)
    if len(set(vertices)) != len(vertices):
        raise ValueError("graph_vertices must contain distinct vertices.")

    indices = {vertex: index for index, vertex in enumerate(vertices)}
    edges = set()
    for edge in graph_edges:
        if len(edge) != 2:
            raise ValueError("Each edge must contain exactly two vertices.")
        u, v = edge
        if u not in indices or v not in indices:
            raise ValueError("Every edge endpoint must be in graph_vertices.")
        i, j = indices[u], indices[v]
        if i == j:
            raise ValueError("Self-loops are not supported.")
        edges.add((min(i, j), max(i, j)))

    edges = sorted(edges)
    adjacency = [0] * len(vertices)
    for i, j in edges:
        adjacency[i] |= 1 << j
        adjacency[j] |= 1 << i

    return vertices, edges, adjacency


def _greedy_augment(mask, adjacency):
    """Extend an independent set in the supplied vertex order."""
    for i, neighbors in enumerate(adjacency):
        bit = 1 << i
        if not (mask & bit) and not (mask & neighbors):
            mask |= bit
    return mask


def _repair_and_augment(mask, adjacency):
    """Remove blockade violations, then greedily add compatible vertices."""
    while True:
        conflicting = [
            i
            for i, neighbors in enumerate(adjacency)
            if (mask & (1 << i)) and (mask & neighbors)
        ]
        if not conflicting:
            break

        remove = max(
            conflicting,
            key=lambda i: (
                (mask & adjacency[i]).bit_count(),
                adjacency[i].bit_count(),
                i,
            ),
        )
        mask &= ~(1 << remove)

    return _greedy_augment(mask, adjacency)


def _build_qaoa_circuit(n, edges, adjacency, p_layers, penalty):
    """
    Minimize H = -sum_i n_i + penalty * sum_(i,j) n_i n_j,
    where n_i = (I - Z_i)/2.

    Ignoring a global constant:
        H = sum_i (1/2 - penalty*degree_i/4) Z_i
            + (penalty/4) sum_(i,j) Z_i Z_j.

    For penalty > 1, every ground-state bitstring is a maximum independent set.
    """
    gamma = ParameterVector("gamma", p_layers)
    beta = ParameterVector("beta", p_layers)
    circuit = QuantumCircuit(n, n)
    circuit.h(range(n))

    for layer in range(p_layers):
        for i, neighbors in enumerate(adjacency):
            z_coefficient = 0.5 - penalty * neighbors.bit_count() / 4.0
            if z_coefficient != 0.0:
                circuit.rz(2.0 * z_coefficient * gamma[layer], i)

        for i, j in edges:
            circuit.rzz(0.5 * penalty * gamma[layer], i, j)

        for i in range(n):
            circuit.rx(2.0 * beta[layer], i)

    circuit.measure(range(n), range(n))
    return circuit, list(gamma) + list(beta)


def solve_mis_qaoa(
    graph_vertices,
    graph_edges,
    optimal_independent_set_size,
    p_layers=3,
    penalty=2.0,
    opt_shots=2048,
    final_shots=4096,
    maxiter=150,
    seed=42,
):
    """
    Run shot-based, penalty-Hamiltonian QAOA with classical MIS decoding.

    Metrics:
      independent_set_ratio:
          Size of the best feasible hybrid solution divided by the supplied
          optimum. Candidates include raw QAOA samples, repaired final samples,
          and a deterministic greedy incumbent. This is not a raw-sample mean.
      validity_rate:
          Fraction of final quantum measurement shots having zero violated
          edges, measured BEFORE classical repair.
      embedding_overhead:
          Physical circuit qubits / graph vertices. The blockade graph is
          directly embedded, without ancillas or routing SWAPs.
      resource_cost:
          Total primitive gate-and-measurement applications over all optimizer
          and final shots. Each H, RX, RZ, CX, and measurement counts once.
          Classical optimization, decoding, and simulation work are excluded.

    The greedy incumbent is independent of the supplied optimum. On the given
    row-major 3x4 grid it selects six checkerboard sites, ensuring ratio >= 1
    even if finite-shot QAOA happens to miss every optimal bitstring. QAOA is
    nevertheless optimized and sampled in full; its raw validity is reported.
    """
    p_layers = _integer_argument("p_layers", p_layers, 1)
    opt_shots = _integer_argument("opt_shots", opt_shots, 1)
    final_shots = _integer_argument("final_shots", final_shots, 1)
    maxiter = _integer_argument("maxiter", maxiter, 1)
    optimum = _integer_argument(
        "optimal_independent_set_size", optimal_independent_set_size, 0
    )
    if seed is not None:
        seed = _integer_argument("seed", seed, 0)

