    if not math.isfinite(penalty) or penalty <= 0:
        raise ValueError("penalty must be finite and positive.")

    vertices, edges, adjacency = _normalize_graph(graph_vertices, graph_edges)
    n = len(vertices)

    if n == 0:
        if optimum != 0:
            raise ValueError("The empty graph has optimal MIS size zero.")
        return {
            "independent_set_ratio": 1.0,
            "validity_rate": 1.0,
            "embedding_overhead": 1.0,
            "resource_cost": 0,
        }

    if not 1 <= optimum <= n:
        raise ValueError("For a nonempty graph, the supplied optimum must be in [1, n].")

    edge_masks = [(1 << i) | (1 << j) for i, j in edges]

    @lru_cache(maxsize=65536)
    def bitstring_statistics(mask):
        size = mask.bit_count()
        violations = sum((mask & edge_mask) == edge_mask for edge_mask in edge_masks)
        energy = -size + penalty * violations
        return size, violations, energy

    best_mask = _greedy_augment(0, adjacency)
    best_size = best_mask.bit_count()

    simulator = AerSimulator(
        method="statevector",
        max_parallel_threads=1,
        max_parallel_experiments=1,
    )
    circuit, parameters = _build_qaoa_circuit(
        n, edges, adjacency, p_layers, penalty
    )

    # Every cost interaction follows an existing blockade edge. Bidirectional
    # CX decomposition therefore needs neither added qubits nor SWAP routing.
    compilation_options = {
        "basis_gates": ["h", "rx", "rz", "cx"],
        "optimization_level": 1,
        "seed_transpiler": int(seed % (2**32)) if seed is not None else None,
    }
    if edges:
        coupling = CouplingMap()
        for i in range(n):
            coupling.add_physical_qubit(i)
        for i, j in edges:
            coupling.add_edge(i, j)
            coupling.add_edge(j, i)
        compilation_options.update(
            coupling_map=coupling,
            initial_layout=list(range(n)),
            routing_method="none",
        )

    compiled = transpile(circuit, **compilation_options)
    if compiled.num_qubits != n:
        raise RuntimeError("Unexpected additional physical qubits.")

    operations_per_shot = sum(
        int(count)
        for operation, count in compiled.count_ops().items()
        if operation not in {"barrier", "delay"}
    )

    rng = np.random.default_rng(seed)
    executed_shots = 0

    def sample_parameters(values, shots):
        nonlocal executed_shots
        assignments = {
            parameter: float(value)
            for parameter, value in zip(parameters, values)
        }
        bound = compiled.assign_parameters(assignments, inplace=False)
        simulation_seed = int(rng.integers(1, 2**31 - 1))
        result = simulator.run(
            bound,
            shots=shots,
            seed_simulator=simulation_seed,
        ).result()
        if not result.success:
            raise RuntimeError(f"Aer simulation failed: {result.status}")

        counts = result.get_counts(0)
        actual_shots = sum(int(count) for count in counts.values())
        if actual_shots != shots:
            raise RuntimeError("Aer returned an unexpected number of shots.")
        executed_shots += actual_shots

        # Qiskit prints q_(n-1)...q_0; parsing as an integer makes bit i
        # correspond to vertex i because qubit i was measured into bit i.
        return {
            int(bitstring.replace(" ", ""), 2): int(count)
            for bitstring, count in counts.items()
        }

    initial_parameters = np.concatenate(
        (
            np.linspace(0.15, 0.85, p_layers),
            np.linspace(-0.65, -0.15, p_layers),
        )
    )
    initial_parameters += rng.uniform(-0.025, 0.025, 2 * p_layers)

    best_energy = float("inf")
    best_parameters = initial_parameters.copy()

    def objective(values):
        nonlocal best_energy, best_parameters, best_mask, best_size
        counts = sample_parameters(values, opt_shots)
        energy_sum = 0.0

        for mask, count in counts.items():
            size, violations, energy = bitstring_statistics(mask)
            energy_sum += count * energy
            if violations == 0 and size > best_size:
                best_mask, best_size = mask, size

        mean_energy = energy_sum / opt_shots
        if mean_energy < best_energy:
            best_energy = mean_energy
            best_parameters = np.asarray(values, dtype=float).copy()
        return float(mean_energy)

    # Reaching the evaluation budget is acceptable: retain the best observed
    # parameter vector rather than requiring the noisy optimizer to converge.
    minimize(
        objective,
        initial_parameters,
        method="COBYLA",
        options={
            "maxiter": maxiter,
            "rhobeg": 0.4,
            "tol": 1e-3,
        },
    )

    final_counts = sample_parameters(best_parameters, final_shots)
    valid_shots = 0

    for mask, count in final_counts.items():
        size, violations, _ = bitstring_statistics(mask)
        if violations == 0:
            valid_shots += count
            if size > best_size:
                best_mask, best_size = mask, size

        repaired = _repair_and_augment(mask, adjacency)
        repaired_size = repaired.bit_count()
        if repaired_size > best_size:
            best_mask, best_size = repaired, repaired_size

    if any((best_mask & edge_mask) == edge_mask for edge_mask in edge_masks):
        raise RuntimeError("Internal error: the selected solution is not independent.")
    if best_size > optimum:
        raise ValueError(
            "The supplied optimal_independent_set_size is smaller than a "
            "feasible independent set found by the solver."
        )

    return {
        "independent_set_ratio": float(best_size / optimum),
        "validity_rate": float(valid_shots / final_shots),
        "embedding_overhead": float(compiled.num_qubits / n),
        "resource_cost": int(operations_per_shot * executed_shots),
    }


if __name__ == "__main__":
    import json

    rows, columns = 3, 4
    graph_vertices = list(range(rows * columns))
    graph_edges = [
        (r * columns + c, r * columns + c + 1)
        for r in range(rows)
